--------------------------------------------------------------------
-- ОБЩИЕ ХЕЛПЕРЫ
--------------------------------------------------------------------
local function child(parent, name, class)
	for _, c in ipairs(parent:GetChildren()) do
		if c.Name == name and c:IsA(class) then return c end
	end
	return nil
end

local function row(panelName, slotName)
	local panel = menu:FindFirstChild(panelName)
	local sc = panel and panel:FindFirstChild("Scroll")
	local slot = sc and sc:FindFirstChild(slotName)
	return slot and slot:FindFirstChild((slotName:gsub("Slot$", "")))
end

local function track(panelName, slotName, fname)
	local r = row(panelName, slotName)
	return r and child(r, fname, "TextButton")
end

-- Свой счётчик состояния: названия тоглов в меню повторяются (functK1 есть в каждой панели),
-- поэтому UI.OnToggle здесь не подходит. Оба обработчика клика стартуют с false и флипаются вместе.
local function hookToggle(btn, onChange)
	if not btn then return end
	local state = false
	btn.MouseButton1Click:Connect(function()
		state = not state
		local ok, err = pcall(onChange, state)
		if not ok then warn("[KOT Hub]", err) end
	end)
end

-- Плавное появление/исчезновение по Transparency
local fadeProps = {
	{ "GuiObject", "BackgroundTransparency" },
	{ "TextLabel", "TextTransparency" },
	{ "TextButton", "TextTransparency" },
	{ "TextBox", "TextTransparency" },
	{ "ImageLabel", "ImageTransparency" },
	{ "ImageButton", "ImageTransparency" },
	{ "UIStroke", "Transparency" },
}

local function collectFade(container)
	local list = {}
	local function add(inst)
		for _, p in ipairs(fadeProps) do
			if inst:IsA(p[1]) then
				local ok, v = pcall(function() return inst[p[2]] end)
				if ok and type(v) == "number" and v < 1 then
					table.insert(list, { inst, p[2], v })
				end
			end
		end
	end
	add(container)
	for _, d in ipairs(container:GetDescendants()) do add(d) end
	return list
end

local function setList(list, visible)
	for _, e in ipairs(list) do
		if e[1].Parent then e[1][e[2]] = visible and e[3] or 1 end
	end
end

local function fadeList(list, toVisible, info)
	for _, e in ipairs(list) do
		if e[1].Parent then
			TweenService:Create(e[1], info, { [e[2]] = toVisible and e[3] or 1 }):Play()
		end
	end
end

