local function newLayer(name)
	local f = Instance.new("Frame")
	f.Name = name
	f.BackgroundTransparency = 1
	f.BorderSizePixel = 0
	f.Size = UDim2.fromScale(1, 1)
	f.Parent = espGui
	return f
end

local function addStroke(parent, thickness, color)
	local s = Instance.new("UIStroke")
	s.Thickness = thickness
	s.Color = color
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	s.LineJoinMode = Enum.LineJoinMode.Miter
	s.Parent = parent
	return s
end

local function newFrame(parent, name)
	local f = Instance.new("Frame")
	f.Name = name
	f.BackgroundTransparency = 1
	f.BorderSizePixel = 0
	f.Parent = parent
	return f
end

local CORNER_ANCHORS = { Vector2.new(0, 0), Vector2.new(1, 0), Vector2.new(0, 1), Vector2.new(1, 1) }

local function projectBounds(cf, size, camera)
	local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
	local any = false
	local hx, hy, hz = size.X / 2, size.Y / 2, size.Z / 2
	for sx = -1, 1, 2 do
		for sy = -1, 1, 2 do
			for sz = -1, 1, 2 do
				local p = camera:WorldToViewportPoint(cf:PointToWorldSpace(Vector3.new(sx * hx, sy * hy, sz * hz)))
				if p.Z > 0 then
					any = true
					if p.X < minX then minX = p.X end
					if p.X > maxX then maxX = p.X end
					if p.Y < minY then minY = p.Y end
					if p.Y > maxY then maxY = p.Y end
				end
			end
		end
	end
	if not any then return nil end
	return minX, minY, maxX, maxY
end

