local function makeESPPlayers()
	local ESP = { Enabled = false }
	local cfg = {
		Style = "Corners", Thickness = 1.5, CornerThickness = 2, CornerLength = 0.28,
		BoxHeightStuds = 6, BoxWidthRatio = 0.6, BoxCenterYOffset = 0,
		ShowHealth = true, ShowName = true, ShowTeam = false, ShowDistance = true,
		HideDead = true, MaxDistance = 5000, TextSize = 14, TextInterval = 0.1,
		NoTeamText = "Без команды", NoTeamColor = Color3.fromRGB(200, 200, 200),
	}
	ESP.Config = cfg
	local layer = newLayer("ESP_Players")
	local entries = {}
	local BIND = "KOT_ESP_Players"

	local function getTeamInfo(plr)
		local team = plr.Team
		if team then return team.Name, team.TeamColor.Color end
		return cfg.NoTeamText, cfg.NoTeamColor
	end

	local function createEntry()
		local e = {}
		e.holder = newFrame(layer, "Box")
		e.holder.Visible = false

		e.boxFrame = newFrame(e.holder, "Full")
		e.boxFrame.Size = UDim2.fromScale(1, 1)
		e.boxOutline = addStroke(e.boxFrame, cfg.Thickness + 2, Color3.new(0, 0, 0))
		local colorFrame = newFrame(e.boxFrame, "Color")
		colorFrame.Size = UDim2.fromScale(1, 1)
		e.boxColor = addStroke(colorFrame, cfg.Thickness, Color3.new(1, 1, 1))

		e.cornerFolder = newFrame(e.holder, "Corners")
		e.cornerFolder.Size = UDim2.fromScale(1, 1)
		e.corners = {}
		for _, anchor in ipairs(CORNER_ANCHORS) do
			for axis = 1, 2 do
				local p = Instance.new("Frame")
				p.BorderSizePixel = 0
				p.BackgroundColor3 = Color3.new(1, 1, 1)
				p.AnchorPoint = anchor
				p.Position = UDim2.fromScale(anchor.X, anchor.Y)
				addStroke(p, 1, Color3.new(0, 0, 0))
				p.Parent = e.cornerFolder
				table.insert(e.corners, { frame = p, horizontal = (axis == 1) })
			end
		end

		e.hpBg = Instance.new("Frame")
		e.hpBg.Name = "HpBg"
		e.hpBg.BorderSizePixel = 0
		e.hpBg.BackgroundColor3 = Color3.new(0, 0, 0)
		e.hpBg.BackgroundTransparency = 0.35
		e.hpBg.AnchorPoint = Vector2.new(1, 0)
		e.hpBg.Position = UDim2.new(0, -5, 0, 0)
		e.hpBg.Size = UDim2.new(0, 4, 1, 0)
		e.hpBg.Parent = e.holder
		e.hpFill = Instance.new("Frame")
		e.hpFill.Name = "Fill"
		e.hpFill.BorderSizePixel = 0
		e.hpFill.AnchorPoint = Vector2.new(0, 1)
		e.hpFill.Position = UDim2.new(0, 1, 1, -1)
		e.hpFill.Size = UDim2.new(1, -2, 1, -2)
		e.hpFill.Parent = e.hpBg

		e.label = Instance.new("TextLabel")
		e.label.Name = "Label"
		e.label.BackgroundTransparency = 1
		e.label.AnchorPoint = Vector2.new(0.5, 1)
		e.label.Position = UDim2.new(0.5, 0, 0, -3)
		e.label.Size = UDim2.fromOffset(220, 60)
		e.label.RichText = true
		e.label.Font = Enum.Font.GothamBold
		e.label.TextColor3 = Color3.new(1, 1, 1)
		e.label.TextStrokeTransparency = 0.4
		e.label.TextYAlignment = Enum.TextYAlignment.Bottom
		e.label.Parent = e.holder

		e.nextText = 0
		return e
	end

	local function destroyEntry(plr)
		local e = entries[plr]
		if not e then return end
		e.holder:Destroy()
		entries[plr] = nil
	end

	local function hideEntry(plr)
		local e = entries[plr]
		if e then e.holder.Visible = false end
	end

	local function updatePlayer(plr, camera)
		if plr == localPlayer then return end
		local char = plr.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not root or not hum or (cfg.HideDead and hum.Health <= 0) then
			hideEntry(plr)
			return
		end

		local rootPos = root.Position
		local half = cfg.BoxHeightStuds / 2
		local mid = rootPos + Vector3.new(0, cfg.BoxCenterYOffset, 0)
		local top = camera:WorldToViewportPoint(mid + Vector3.new(0, half, 0))
		local bottom = camera:WorldToViewportPoint(mid - Vector3.new(0, half, 0))
		if top.Z <= 0 or bottom.Z <= 0 then
			hideEntry(plr)
			return
		end

		local dist = (camera.CFrame.Position - rootPos).Magnitude
		if dist > cfg.MaxDistance then
			hideEntry(plr)
			return
		end

		local height = math.max(4, math.floor(bottom.Y - top.Y + 0.5))
		local width = math.max(2, math.floor(height * cfg.BoxWidthRatio + 0.5))
		local x = math.floor((top.X + bottom.X) / 2 - width / 2 + 0.5)
		local y = math.floor(top.Y + 0.5)

		local e = entries[plr]
		if not e then
			e = createEntry()
			entries[plr] = e
		end

		e.holder.Position = UDim2.fromOffset(x, y)
		e.holder.Size = UDim2.fromOffset(width, height)
		e.holder.Visible = true

		local _, color = getTeamInfo(plr)

		local isBox = (cfg.Style == "Box")
		e.boxFrame.Visible = isBox
		e.cornerFolder.Visible = not isBox
		if isBox then
			e.boxColor.Color = color
			e.boxColor.Thickness = cfg.Thickness
			e.boxOutline.Thickness = cfg.Thickness + 2
		else
			local len = math.clamp(math.floor(math.min(width, height) * cfg.CornerLength + 0.5), 4, 40)
			local t = cfg.CornerThickness
			for _, c in ipairs(e.corners) do
				c.frame.BackgroundColor3 = color
				c.frame.Size = c.horizontal and UDim2.fromOffset(len, t) or UDim2.fromOffset(t, len)
			end
		end

		e.hpBg.Visible = cfg.ShowHealth
		if cfg.ShowHealth then
			local ratio = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
			e.hpFill.Size = UDim2.new(1, -2, ratio, ratio > 0 and -2 or 0)
			e.hpFill.BackgroundColor3 = Color3.fromRGB(255, 60, 60):Lerp(Color3.fromRGB(70, 255, 120), ratio)
		end

		local now = os.clock()
		if now >= e.nextText then
			e.nextText = now + cfg.TextInterval
			local teamName = getTeamInfo(plr)
			local lines = {}
			if cfg.ShowName then table.insert(lines, plr.DisplayName) end
			if cfg.ShowTeam then
				table.insert(lines, string.format('<font color="#%s">%s</font>', color:ToHex(), teamName))
			end
			if cfg.ShowDistance then
				table.insert(lines, string.format("[%d м]", math.floor(dist + 0.5)))
			end
			e.label.TextSize = cfg.TextSize
			e.label.Text = table.concat(lines, "\n")
		end
	end

	local function step()
		local camera = workspace.CurrentCamera
		if not camera then return end
		for _, plr in ipairs(Players:GetPlayers()) do
			updatePlayer(plr, camera)
		end
	end

	local function clearAll()
		for plr in pairs(entries) do destroyEntry(plr) end
	end

	function ESP.Enable()
		if ESP.Enabled then return end
		ESP.Enabled = true
		RunService:BindToRenderStep(BIND, Enum.RenderPriority.Camera.Value + 1, step)
	end

	function ESP.Disable()
		if not ESP.Enabled then return end
		ESP.Enabled = false
		pcall(function() RunService:UnbindFromRenderStep(BIND) end)
		clearAll()
	end

	Players.PlayerRemoving:Connect(destroyEntry)
	return ESP
end

--------------------------------------------------------------------
-- ESP GENERATORS
--------------------------------------------------------------------
local function makeESPGens()
	local ESP = { Enabled = false }
	local cfg = {
		Style = "Box", BoxColor = Color3.fromRGB(255, 205, 60), Thickness = 1.5,
		CornerThickness = 2, CornerLength = 0.22, Padding = 2, MinSize = 14, MaxDistance = 2000,
		MinVisibleTransparency = 0.9, BoxScale = 0.85, MaxStuds = 10,
		ColorTodo = Color3.fromRGB(235, 64, 64), ColorDone = Color3.fromRGB(70, 230, 120), BarWidth = 3,
		Font = Enum.Font.SpecialElite, TextSize = 15, MinTextSize = 10, TextTilt = -3, WearAmount = 0.5,
		ScanInterval = 0.5, BoundsInterval = 1,
		FolderPatterns = { "generator", "gens" }, FolderExact = { "gen" },
		FallbackScan = true, FallbackInterval = 2,
	}
	ESP.Config = cfg
	local layer = newLayer("ESP_Gens")
	local entries = {}
	local gensFolder = nil
	local BIND = "KOT_ESP_Gens"

	local function isFolderName(name)
		name = string.lower(name)
		for _, n in ipairs(cfg.FolderExact) do
			if name == n then return true end
		end
		for _, p in ipairs(cfg.FolderPatterns) do
			if string.find(name, p, 1, true) then return true end
		end
		return false
	end

	local function findGensFolder(map)
		for _, c in ipairs(map:GetChildren()) do
			if isFolderName(c.Name) then return c end
		end
		for _, d in ipairs(map:GetDescendants()) do
			if (d:IsA("Folder") or d:IsA("Model")) and isFolderName(d.Name) then return d end
		end
		return nil
	end

	local function hasAttrs(inst)
		return inst:GetAttribute("RepairProgress") ~= nil or inst:GetAttribute("Completed") ~= nil
	end

	local function findAttrHolder(inst)
		if hasAttrs(inst) then return inst end
		for _, d in ipairs(inst:GetDescendants()) do
			if hasAttrs(d) then return d end
		end
		return nil
	end

	local function getBounds(inst)
		if inst:IsA("BasePart") then return inst.CFrame, inst.Size end
		if not inst:IsA("Model") then return nil, nil end

		local pivot = inst:GetPivot()
		local minV = Vector3.new(math.huge, math.huge, math.huge)
		local maxV = Vector3.new(-math.huge, -math.huge, -math.huge)
		local found = false

		for _, d in ipairs(inst:GetDescendants()) do
			if d:IsA("BasePart") and d.Transparency < cfg.MinVisibleTransparency then
				local s = d.Size / 2
				for sx = -1, 1, 2 do
					for sy = -1, 1, 2 do
						for sz = -1, 1, 2 do
							local p = pivot:PointToObjectSpace(d.CFrame:PointToWorldSpace(Vector3.new(sx * s.X, sy * s.Y, sz * s.Z)))
							minV = Vector3.new(math.min(minV.X, p.X), math.min(minV.Y, p.Y), math.min(minV.Z, p.Z))
							maxV = Vector3.new(math.max(maxV.X, p.X), math.max(maxV.Y, p.Y), math.max(maxV.Z, p.Z))
							found = true
						end
					end
				end
			end
		end

		if not found then return inst:GetBoundingBox() end

		local size = (maxV - minV) * cfg.BoxScale
		local cap = cfg.MaxStuds
		if cap then
			size = Vector3.new(math.min(size.X, cap), math.min(size.Y, cap), math.min(size.Z, cap))
		end
		return pivot * CFrame.new((minV + maxV) / 2), size
	end

	local function wearSequence(seed)
		local rng = Random.new(seed)
		local points = {}
		local count = 14
		for i = 0, count do
			local v
			if rng:NextNumber() < 0.45 then
				v = rng:NextNumber(0.25, 0.7) * cfg.WearAmount
			else
				v = rng:NextNumber(0, 0.12) * cfg.WearAmount
			end
			table.insert(points, NumberSequenceKeypoint.new(i / count, v))
		end
		return NumberSequence.new(points)
	end

	local function createEntry(key, holder)
		local e = { key = key, holder = holder, nextBounds = 0 }

		e.root = newFrame(layer, "GenBox")
		e.root.Visible = false

		e.boxFrame = newFrame(e.root, "Full")
		e.boxFrame.Size = UDim2.fromScale(1, 1)
		addStroke(e.boxFrame, cfg.Thickness + 2, Color3.new(0, 0, 0))
		local colorFrame = newFrame(e.boxFrame, "Color")
		colorFrame.Size = UDim2.fromScale(1, 1)
		e.boxStroke = addStroke(colorFrame, cfg.Thickness, cfg.BoxColor)

		e.cornerFolder = newFrame(e.root, "Corners")
		e.cornerFolder.Size = UDim2.fromScale(1, 1)
		e.corners = {}
		for _, anchor in ipairs(CORNER_ANCHORS) do
			for axis = 1, 2 do
				local p = Instance.new("Frame")
				p.BorderSizePixel = 0
				p.BackgroundColor3 = cfg.BoxColor
				p.AnchorPoint = anchor
				p.Position = UDim2.fromScale(anchor.X, anchor.Y)
				addStroke(p, 1, Color3.new(0, 0, 0))
				p.Parent = e.cornerFolder
				table.insert(e.corners, { frame = p, horizontal = (axis == 1) })
			end
		end

		e.barBg = Instance.new("Frame")
		e.barBg.Name = "BarBg"
		e.barBg.BorderSizePixel = 0
		e.barBg.BackgroundColor3 = Color3.new(0, 0, 0)
		e.barBg.BackgroundTransparency = 0.35
		e.barBg.AnchorPoint = Vector2.new(1, 0)
		e.barBg.Position = UDim2.new(0, -5, 0, 0)
		e.barBg.Size = UDim2.new(0, cfg.BarWidth, 1, 0)
		e.barBg.Parent = e.root
		e.barFill = Instance.new("Frame")
		e.barFill.Name = "Fill"
		e.barFill.BorderSizePixel = 0
		e.barFill.AnchorPoint = Vector2.new(0, 1)
		e.barFill.Position = UDim2.new(0, 1, 1, -1)
		e.barFill.Size = UDim2.new(1, -2, 0, 0)
		e.barFill.Parent = e.barBg

		e.label = Instance.new("TextLabel")
		e.label.Name = "Percent"
		e.label.BackgroundTransparency = 1
		e.label.AnchorPoint = Vector2.new(0, 0.5)
		e.label.Position = UDim2.new(1, 7, 0.5, 0)
		e.label.Size = UDim2.fromOffset(60, 24)
		e.label.Font = cfg.Font
		e.label.TextSize = cfg.TextSize
		e.label.TextXAlignment = Enum.TextXAlignment.Left
		e.label.Rotation = cfg.TextTilt
		e.label.Text = "0%"
		e.label.Parent = e.root

		local textStroke = Instance.new("UIStroke")
		textStroke.Color = Color3.new(0, 0, 0)
		textStroke.Thickness = 1.5
		textStroke.Transparency = 0.25
		textStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
		textStroke.Parent = e.label

		local wear = Instance.new("UIGradient")
		wear.Transparency = wearSequence(#key.Name * 131 + math.floor(os.clock() * 1000) % 997)
		wear.Rotation = 25
		wear.Parent = e.label

		return e
	end

	local function destroyEntry(key)
		local e = entries[key]
		if not e then return end
		e.root:Destroy()
		entries[key] = nil
	end

	local function clearAll()
		for key in pairs(entries) do destroyEntry(key) end
	end

	local function applyState(e, done)
		local color = done and cfg.ColorDone or cfg.ColorTodo
		local textColor = color:Lerp(Color3.new(1, 1, 1), 0.65)
		if e.done == nil then
			e.barFill.BackgroundColor3 = color
			e.label.TextColor3 = textColor
		else
			local info = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			TweenService:Create(e.barFill, info, { BackgroundColor3 = color }):Play()
			TweenService:Create(e.label, info, { TextColor3 = textColor }):Play()
		end
		e.done = done
	end

	local function updateEntry(key, e, camera)
		if not key:IsDescendantOf(workspace) or not e.holder:IsDescendantOf(workspace) then
			destroyEntry(key)
			return
		end

		local now = os.clock()
		if not e.cf or now >= e.nextBounds then
			local cf, size = getBounds(key)
			if cf then e.cf, e.size = cf, size end
			e.nextBounds = now + cfg.BoundsInterval
		end
		if not e.cf then
			e.root.Visible = false
			return
		end

		local dist = (camera.CFrame.Position - e.cf.Position).Magnitude
		if dist > cfg.MaxDistance then
			e.root.Visible = false
			return
		end

		local minX, minY, maxX, maxY = projectBounds(e.cf, e.size, camera)
		if not minX then
			e.root.Visible = false
			return
		end

		local pad = cfg.Padding
		local w = math.max(cfg.MinSize, math.floor(maxX - minX + pad * 2 + 0.5))
		local h = math.max(cfg.MinSize, math.floor(maxY - minY + pad * 2 + 0.5))
		local x = math.floor((minX + maxX) / 2 - w / 2 + 0.5)
		local y = math.floor((minY + maxY) / 2 - h / 2 + 0.5)

		e.root.Position = UDim2.fromOffset(x, y)
		e.root.Size = UDim2.fromOffset(w, h)
		e.root.Visible = true

		local isBox = (cfg.Style == "Box")
		e.boxFrame.Visible = isBox
		e.cornerFolder.Visible = not isBox
		if isBox then
			e.boxStroke.Color = cfg.BoxColor
			e.boxStroke.Thickness = cfg.Thickness
		else
			local len = math.clamp(math.floor(math.min(w, h) * cfg.CornerLength + 0.5), 4, 60)
			local t = cfg.CornerThickness
			for _, c in ipairs(e.corners) do
				c.frame.BackgroundColor3 = cfg.BoxColor
				c.frame.Size = c.horizontal and UDim2.fromOffset(len, t) or UDim2.fromOffset(t, len)
			end
		end

		local progress = tonumber(e.holder:GetAttribute("RepairProgress")) or 0
		local done = e.holder:GetAttribute("Completed") == true or progress >= 100
		local pct = done and 100 or math.clamp(math.floor(progress + 0.5), 0, 100)

		if e.done ~= done then applyState(e, done) end

		local ratio = pct / 100
		e.barFill.Size = UDim2.new(1, -2, ratio, ratio > 0 and -2 or 0)
		e.label.TextSize = math.clamp(math.floor(h * 0.3), cfg.MinTextSize, cfg.TextSize)

		local text = string.format("%d%%", pct)
		if e.text ~= text then
			e.text = text
			e.label.Text = text
		end
	end

	local function tryRegister(c)
		if entries[c] then return end
		local holder = findAttrHolder(c)
		if holder and getBounds(c) then
			entries[c] = createEntry(c, holder)
		end
	end

	local lastFallback = 0
	local function fallbackScan(map)
		local now = os.clock()
		if now - lastFallback < cfg.FallbackInterval then return end
		lastFallback = now
		for _, d in ipairs(map:GetDescendants()) do
			if (d:IsA("Model") or d:IsA("BasePart")) and hasAttrs(d) then
				tryRegister(d)
			end
		end
	end

	local function scan()
		local map = workspace:FindFirstChild("Map")
		if not map then
			gensFolder = nil
			clearAll()
			return
		end
		if not gensFolder or not gensFolder:IsDescendantOf(map) then
			gensFolder = findGensFolder(map)
		end
		if gensFolder then
			for _, c in ipairs(gensFolder:GetChildren()) do tryRegister(c) end
		end
		if cfg.FallbackScan and next(entries) == nil then
			fallbackScan(map)
		end
	end

	local scanAcc = 0
	local function step(dt)
		local camera = workspace.CurrentCamera
		if not camera then return end
		scanAcc += dt
		if scanAcc >= cfg.ScanInterval then
			scanAcc = 0
			scan()
		end
		for key, e in pairs(entries) do
			updateEntry(key, e, camera)
		end
	end

	function ESP.Enable()
		if ESP.Enabled then return end
		ESP.Enabled = true
		scanAcc = 0
		scan()
		RunService:BindToRenderStep(BIND, Enum.RenderPriority.Camera.Value + 1, step)
	end

	function ESP.Disable()
		if not ESP.Enabled then return end
		ESP.Enabled = false
		pcall(function() RunService:UnbindFromRenderStep(BIND) end)
		gensFolder = nil
		clearAll()
	end

	return ESP
end

--------------------------------------------------------------------
-- ESP EVENT (тыквы)
--------------------------------------------------------------------
local function makeESPPumpkins()
	local ESP = { Enabled = false }
	local cfg = {
		FolderNames = { "Pumkins", "Pumpkins" },
		BoxColor = Color3.fromRGB(255, 140, 0), Thickness = 1.5, Padding = 2, MinSize = 12,
		MaxDistance = 2000, ScanInterval = 0.5, BoundsInterval = 1,
	}
	ESP.Config = cfg
	local layer = newLayer("ESP_Pumpkins")
	local entries = {}
	local BIND = "KOT_ESP_Pumpkins"

	local function findFolder(map)
		for _, name in ipairs(cfg.FolderNames) do
			local f = map:FindFirstChild(name)
			if f then return f end
		end
		return nil
	end

	local function getBounds(inst)
		if inst:IsA("BasePart") then return inst.CFrame, inst.Size
		elseif inst:IsA("Model") then return inst:GetBoundingBox() end
		return nil, nil
	end

	local function createEntry()
		local e = { nextBounds = 0 }
		e.root = newFrame(layer, "PumpkinBox")
		e.root.Visible = false
		local outline = newFrame(e.root, "Outline")
		outline.Size = UDim2.fromScale(1, 1)
		addStroke(outline, cfg.Thickness + 2, Color3.new(0, 0, 0))
		local colorFrame = newFrame(e.root, "Color")
		colorFrame.Size = UDim2.fromScale(1, 1)
		addStroke(colorFrame, cfg.Thickness, cfg.BoxColor)
		return e
	end

	local function destroyEntry(key)
		local e = entries[key]
		if not e then return end
		e.root:Destroy()
		entries[key] = nil
	end

	local function clearAll()
		for key in pairs(entries) do destroyEntry(key) end
	end

	local function updateEntry(key, e, camera)
		if not key:IsDescendantOf(workspace) then
			destroyEntry(key)
			return
		end
		local now = os.clock()
		if not e.cf or now >= e.nextBounds then
			local cf, size = getBounds(key)
			if cf then e.cf, e.size = cf, size end
			e.nextBounds = now + cfg.BoundsInterval
		end
		if not e.cf then
			e.root.Visible = false
			return
		end
		if (camera.CFrame.Position - e.cf.Position).Magnitude > cfg.MaxDistance then
			e.root.Visible = false
			return
		end
		local minX, minY, maxX, maxY = projectBounds(e.cf, e.size, camera)
		if not minX then
			e.root.Visible = false
			return
		end
		local pad = cfg.Padding
		local w = math.max(cfg.MinSize, math.floor(maxX - minX + pad * 2 + 0.5))
		local h = math.max(cfg.MinSize, math.floor(maxY - minY + pad * 2 + 0.5))
		local x = math.floor((minX + maxX) / 2 - w / 2 + 0.5)
		local y = math.floor((minY + maxY) / 2 - h / 2 + 0.5)
		e.root.Position = UDim2.fromOffset(x, y)
		e.root.Size = UDim2.fromOffset(w, h)
		e.root.Visible = true
	end

	local function scan()
		local map = workspace:FindFirstChild("Map")
		if not map then clearAll() return end
		local folder = findFolder(map)
		if not folder then clearAll() return end
		for _, c in ipairs(folder:GetChildren()) do
			if not entries[c] and (c:IsA("Model") or c:IsA("BasePart")) then
				entries[c] = createEntry()
			end
		end
	end

	local scanAcc = 0
	local function step(dt)
		local camera = workspace.CurrentCamera
		if not camera then return end
		scanAcc += dt
		if scanAcc >= cfg.ScanInterval then
			scanAcc = 0
			scan()
		end
		for key, e in pairs(entries) do
			updateEntry(key, e, camera)
		end
	end

	function ESP.Enable()
		if ESP.Enabled then return end
		ESP.Enabled = true
		scanAcc = 0
		scan()
		RunService:BindToRenderStep(BIND, Enum.RenderPriority.Camera.Value + 1, step)
	end

	function ESP.Disable()
		if not ESP.Enabled then return end
		ESP.Enabled = false
		pcall(function() RunService:UnbindFromRenderStep(BIND) end)
		clearAll()
	end

	return ESP
end

--------------------------------------------------------------------
-- AUTO SKILLCHECK (раздельно: Generator / Player)
--------------------------------------------------------------------
local function makeAutoSkill()
	local S = { Gen = false, Player = false }
	local cfg = {
		WindowStart = 102, WindowEnd = 116,
		Humanize = true, TargetMin = 106, TargetMax = 111,
		Latency = 0.015, AutoCalibrate = true, EarlyGuard = 3, PressTime = 0.03,
		KeyOverride = nil, FallbackKey = Enum.KeyCode.Space,
		-- Определение, какой это скилчек (игра у всех использует один и тот же GUI):
		GenRange = 12,            -- генератор ближе стольких студов -> считаем скилчеком генератора
		PlayerRange = 9,          -- другой игрок ближе стольких студов -> считаем лечением
		PressWhenUnknown = true,  -- если не понятно (например King Scourge): жать, если включена любая из двух кнопок
		Debug = false,
	}
	S.Config = cfg

	local rng = Random.new()
	local vim = nil
	do
		local ok, svc = pcall(function() return game:GetService("VirtualInputManager") end)
		if ok then vim = svc end
	end

	local cachedKey = nil
	local function log(...)
		if cfg.Debug then print("[AutoSkillCheck]", ...) end
	end

	local function resolveKey()
		if cfg.KeyOverride then return cfg.KeyOverride end
		if cachedKey then return cachedKey end
		local modules = ReplicatedStorage:FindFirstChild("Modules")
		local survivors = modules and modules:FindFirstChild("Survivors")
		local module = survivors and survivors:FindFirstChild("KeybindsConfig")
		if module then
			local ok, mod = pcall(require, module)
			if ok and type(mod) == "table" and type(mod.matches) == "function" then
				for _, kc in ipairs(Enum.KeyCode:GetEnumItems()) do
					if kc ~= Enum.KeyCode.Unknown then
						local fake = {
							KeyCode = kc,
							UserInputType = Enum.UserInputType.Keyboard,
							UserInputState = Enum.UserInputState.Begin,
						}
						local ok2, res = pcall(mod.matches, "skillcheck", fake)
						if ok2 and res == true then
							cachedKey = kc
							log("клавиша скилчека:", kc.Name)
							return kc
						end
					end
				end
			end
		end
		cachedKey = cfg.FallbackKey
		return cachedKey
	end

	local function pressKey()
		if not vim then return end
		local key = resolveKey()
		task.spawn(function()
			pcall(function() vim:SendKeyEvent(true, key, false, game) end)
			task.wait(cfg.PressTime)
			pcall(function() vim:SendKeyEvent(false, key, false, game) end)
		end)
	end

	local checkGui, lineGui, goalGui
	local function resolveGui()
		if checkGui and checkGui.Parent and lineGui and lineGui.Parent and goalGui and goalGui.Parent then
			return true
		end
		local prompt = playerGui:FindFirstChild("SkillCheckPromptGui")
		local check = prompt and prompt:FindFirstChild("Check")
		local line = check and check:FindFirstChild("Line")
		local goal = check and check:FindFirstChild("Goal")
		if check and line and goal then
			checkGui, lineGui, goalGui = check, line, goal
			return true
		end
		return false
	end

	-- Эвристика: что рядом — незавершённый генератор или другой игрок
	local function getContext()
		local char = localPlayer.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root then return "unknown" end
		local pos = root.Position

		local dGen = math.huge
		local map = workspace:FindFirstChild("Map")
		if map then
			for _, d in ipairs(map:GetDescendants()) do
				if (d:IsA("Model") or d:IsA("BasePart"))
					and (d:GetAttribute("RepairProgress") ~= nil or d:GetAttribute("Completed") ~= nil) then
					local prog = tonumber(d:GetAttribute("RepairProgress")) or 0
					if d:GetAttribute("Completed") ~= true and prog < 100 then
						local p = d:IsA("Model") and d:GetPivot().Position or d.Position
						local dist = (p - pos).Magnitude
						if dist < dGen then dGen = dist end
					end
				end
			end
		end

		local dPlr = math.huge
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= localPlayer then
				local r = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
				if r then
					local dd = (r.Position - pos).Magnitude
					if dd < dPlr then dPlr = dd end
				end
			end
		end

		log(string.format("dGen=%.1f dPlayer=%.1f", dGen, dPlr))
		if dGen <= cfg.GenRange and (dGen <= dPlr or dPlr > cfg.PlayerRange) then return "gen" end
		if dPlr <= cfg.PlayerRange then return "player" end
		return "unknown"
	end

	local function allowed(ctx)
		if ctx == "gen" then return S.Gen end
		if ctx == "player" then return S.Player end
		return cfg.PressWhenUnknown and (S.Gen or S.Player)
	end

	local armed, lockedGoal, offset = true, nil, nil
	local lastRot, lastTime = nil, nil
	local pending = nil
	local ctx = nil
	local connection = nil

	local function newOffset()
		if cfg.Humanize then return rng:NextNumber(cfg.TargetMin, cfg.TargetMax) end
		return (cfg.WindowStart + cfg.WindowEnd) / 2
	end

	local function step()
		if not resolveGui() then return end

		if not checkGui.Visible then
			armed, lockedGoal, offset = true, nil, nil
			lastRot, lastTime = nil, nil
			ctx = nil
			return
		end

		if ctx == nil then
			ctx = getContext()
			log("контекст скилчека:", ctx)
		end
		if not allowed(ctx) then return end

		local rot = lineGui.Rotation
		local goal = goalGui.Rotation
		local now = os.clock()

		local speed = 0
		if lastRot and lastTime and now > lastTime then
			speed = (rot - lastRot) / (now - lastTime)
		end
		lastRot, lastTime = rot, now

		if lockedGoal and math.abs(goal - lockedGoal) > 0.5 then
			armed, lockedGoal, offset = true, nil, nil
		end

		if not armed then return end
		if speed < 20 then return end

		offset = offset or newOffset()
		local predicted = rot + speed * cfg.Latency
		local targetRot = goal + offset

		if predicted >= targetRot
			and rot >= goal + cfg.WindowStart - cfg.EarlyGuard
			and rot <= goal + cfg.WindowEnd then
			armed = false
			lockedGoal = goal
			pending = { goal = goal, offset = offset, speed = speed, time = now }
			log(string.format("жму: rot=%.1f goal=%.1f target=%.1f speed=%.0f", rot, goal, targetRot, speed))
			pressKey()
		end
	end

	local function refresh()
		local need = S.Gen or S.Player
		if need and not connection then
			armed, lockedGoal, offset, lastRot, lastTime, ctx = true, nil, nil, nil, nil, nil
			connection = RunService.RenderStepped:Connect(step)
			if not vim then warn("[AutoSkillCheck] VirtualInputManager недоступен — нажатие не сработает") end
		elseif not need and connection then
			connection:Disconnect()
			connection = nil
		end
	end

	function S.SetGen(v) S.Gen = v and true or false; refresh() end
	function S.SetPlayer(v) S.Player = v and true or false; refresh() end

	-- автокалибровка Latency
	UserInputService.InputBegan:Connect(function(input)
		if not pending or not connection then return end
		if input.KeyCode ~= resolveKey() then return end
		if os.clock() - pending.time > 0.3 then pending = nil return end
		if not resolveGui() then return end
		local landed = lineGui.Rotation - pending.goal
		local err = landed - pending.offset
		log(string.format("нажатие дошло на %.1f°, ошибка %+.1f°", landed, err))
		if cfg.AutoCalibrate and pending.speed > 20 then
			cfg.Latency = math.clamp(cfg.Latency + (err / pending.speed) * 0.7, 0, 0.12)
		end
		pending = nil
	end)

	return S
end

--------------------------------------------------------------------
-- FULLBRIGHT / NOFOG (разделено)
-- NoFog = убирает туман Lighting/Atmosphere + дым (как было в NoSmoke)
--------------------------------------------------------------------
local function makeVisuals()
	local C = {
		Brightness = 2, ClockTime = 14, AmbientColor = Color3.fromRGB(200, 200, 200), ExposureCompensation = 0,
		KillAllParticles = false,
		SmokeKeywords = { "smoke", "дым", "fog", "gas", "cloud", "steam", "mist" },
		RemoveFog = true,
		WatchdogInterval = 1, SmokeScanInterval = 5,
		ReapplyDelayAfterRespawn = 0.6, ReapplyDelayAfterMapChange = 0.8,
	}
	local state = { Fullbright = false, NoFog = false }

	local lightingProps = { "Brightness", "GlobalShadows", "Ambient", "OutdoorAmbient", "ClockTime", "ExposureCompensation" }
	local fogProps = { "FogEnd", "FogStart" }
	local orig = {}
	local origAtm = setmetatable({}, { __mode = "k" })
	local applying = false

	local function saveOriginals()
		if next(orig) ~= nil then return end
		for _, p in ipairs(lightingProps) do orig[p] = Lighting[p] end
		for _, p in ipairs(fogProps) do orig[p] = Lighting[p] end
	end

	local function fbTargets()
		return {
			Brightness = C.Brightness, GlobalShadows = false,
			Ambient = C.AmbientColor, OutdoorAmbient = C.AmbientColor,
			ClockTime = C.ClockTime, ExposureCompensation = C.ExposureCompensation,
		}
	end

	local function applyFullbright()
		saveOriginals()
		applying = true
		for prop, value in pairs(fbTargets()) do
			if Lighting[prop] ~= value then Lighting[prop] = value end
		end
		applying = false
	end

	local function restoreFullbright()
		applying = true
		for _, p in ipairs(lightingProps) do
			if orig[p] ~= nil then Lighting[p] = orig[p] end
		end
		applying = false
	end

	local function fbWorking()
		for prop, value in pairs(fbTargets()) do
			if Lighting[prop] ~= value then return false end
		end
		return true
	end

	-- дым
	local smokeObjects = setmetatable({}, { __mode = "k" })
	local smokeConns = setmetatable({}, { __mode = "k" })

	local function looksLikeSmoke(name)
		name = string.lower(name)
		for _, kw in ipairs(C.SmokeKeywords) do
			if string.find(name, kw, 1, true) then return true end
		end
		return false
	end

	local function isSmoke(inst)
		if inst:IsA("Smoke") then return true end
		if inst:IsA("ParticleEmitter") then
			if C.KillAllParticles then return true end
			if looksLikeSmoke(inst.Name) then return true end
			local parent = inst.Parent
			if parent and looksLikeSmoke(parent.Name) then return true end
		end
		return false
	end

	local function killSmoke(inst)
		if smokeObjects[inst] == nil then smokeObjects[inst] = inst.Enabled end
		if inst.Enabled then inst.Enabled = false end
		if inst:IsA("ParticleEmitter") then inst:Clear() end
		if not smokeConns[inst] then
			smokeConns[inst] = inst:GetPropertyChangedSignal("Enabled"):Connect(function()
				if state.NoFog and inst.Enabled then
					inst.Enabled = false
					if inst:IsA("ParticleEmitter") then inst:Clear() end
				end
			end)
		end
	end

	local function applyFog()
		if not C.RemoveFog then return end
		saveOriginals() -- исправление: оригиналы сохраняются и когда включён только NoFog
		applying = true
		if Lighting.FogEnd < 1e6 then Lighting.FogEnd = 1e6 end
		applying = false
		for _, c in ipairs(Lighting:GetChildren()) do
			if c:IsA("Atmosphere") then
				if origAtm[c] == nil then origAtm[c] = { Density = c.Density, Haze = c.Haze } end
				c.Density = 0
				c.Haze = 0
			end
		end
	end

	local function restoreFog()
		applying = true
		if orig.FogEnd ~= nil then
			Lighting.FogEnd = orig.FogEnd
			Lighting.FogStart = orig.FogStart
		end
		applying = false
		for atm, o in pairs(origAtm) do
			if atm.Parent then
				atm.Density = o.Density
				atm.Haze = o.Haze
			end
		end
	end

	local function scanSmoke()
		local function scan(root)
			for i, inst in ipairs(root:GetDescendants()) do
				if isSmoke(inst) then killSmoke(inst) end
				if i % 2000 == 0 then task.wait() end
			end
		end
		scan(workspace)
		scan(Lighting)
		applyFog()
	end

	local function restoreSmoke()
		for inst, wasEnabled in pairs(smokeObjects) do
			if smokeConns[inst] then
				smokeConns[inst]:Disconnect()
				smokeConns[inst] = nil
			end
			if inst.Parent then inst.Enabled = wasEnabled end
		end
		table.clear(smokeObjects)
		restoreFog()
	end

	local function activeSmoke()
		local n = 0
		for inst in pairs(smokeObjects) do
			if inst.Parent and inst.Enabled then n += 1 end
		end
		return n
	end

	local function noFogWorking()
		if activeSmoke() > 0 then return false end
		if C.RemoveFog and Lighting.FogEnd < 1e6 then return false end
		return true
	end

	local function reapplyAll()
		if state.Fullbright then applyFullbright() end
		if state.NoFog then task.spawn(scanSmoke) end
	end

	local pendingReapply = false
	local function scheduleReapply(delaySec)
		if pendingReapply then return end
		pendingReapply = true
		task.delay(delaySec, function()
			pendingReapply = false
			reapplyAll()
		end)
	end

	local API = {}
	function API.SetFullbright(enabled)
		state.Fullbright = enabled and true or false
		if state.Fullbright then
			applyFullbright()
		else
			restoreFullbright()
			if state.NoFog then applyFog() end
		end
	end
	function API.SetNoFog(enabled)
		state.NoFog = enabled and true or false
		if state.NoFog then
			task.spawn(scanSmoke)
		else
			restoreSmoke()
		end
	end
	shared.AdminVisuals = {
		SetFullbright = API.SetFullbright,
		SetNoSmoke = API.SetNoFog,
		SetNoFog = API.SetNoFog,
	}

	local function onCharacter(char)
		scheduleReapply(C.ReapplyDelayAfterRespawn)
		local hum = char:WaitForChild("Humanoid", 10)
		if hum then
			hum.Died:Connect(function() scheduleReapply(C.ReapplyDelayAfterRespawn) end)
		end
	end
	localPlayer.CharacterAdded:Connect(onCharacter)
	if localPlayer.Character then task.spawn(onCharacter, localPlayer.Character) end

	workspace.ChildAdded:Connect(function()
		if state.Fullbright or state.NoFog then scheduleReapply(C.ReapplyDelayAfterMapChange) end
	end)
	workspace.DescendantAdded:Connect(function(inst)
		if state.NoFog and isSmoke(inst) then killSmoke(inst) end
	end)
	Lighting.DescendantAdded:Connect(function(inst)
		if state.NoFog and isSmoke(inst) then killSmoke(inst) end
		if state.NoFog and inst:IsA("Atmosphere") then task.defer(applyFog) end
	end)

	for _, prop in ipairs(lightingProps) do
		Lighting:GetPropertyChangedSignal(prop):Connect(function()
			if applying or not state.Fullbright then return end
			if not fbWorking() then scheduleReapply(0.05) end
		end)
	end
	for _, prop in ipairs(fogProps) do
		Lighting:GetPropertyChangedSignal(prop):Connect(function()
			if applying or not (state.NoFog and C.RemoveFog) then return end
			task.defer(applyFog)
		end)
	end

	local acc, smokeAcc = 0, 0
	RunService.Heartbeat:Connect(function(dt)
		acc += dt
		smokeAcc += dt
		if acc < C.WatchdogInterval then return end
		acc = 0
		if state.Fullbright and not fbWorking() then applyFullbright() end
		if state.NoFog then
			if smokeAcc >= C.SmokeScanInterval then
				smokeAcc = 0
				task.spawn(scanSmoke)
			end
			if not noFogWorking() then
				for inst in pairs(smokeObjects) do
					if inst.Parent and inst.Enabled then killSmoke(inst) end
				end
				applyFog()
			end
		end
	end)

	return API
end

