local cursorConn = nil
local function setCursor(on)
	if on then
		if cursorConn then return end
		cursorFrame.Size = UDim2.fromOffset(60, 60)
		cursorFrame.Visible = true
		cursorConn = RunService.RenderStepped:Connect(function()
			UserInputService.MouseIconEnabled = false
			local m = UserInputService:GetMouseLocation()
			cursorFrame.Position = UDim2.fromOffset(m.X, m.Y)
		end)
	else
		if cursorConn then cursorConn:Disconnect() cursorConn = nil end
		cursorFrame.Visible = false
		UserInputService.MouseIconEnabled = true
	end
end

