-- РАЗМЕР МЕНЮ / ОТКРЫТИЕ / ЗАГРУЗКА
--------------------------------------------------------------------
local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
local userPercent = 100   -- размер меню в процентах (Settings)
local mobileDiv = 1.5     -- во сколько раз уменьшать на телефоне (1.5 или 2)

local sizeScale = Instance.new("UIScale")
sizeScale.Name = "SizeScale"
sizeScale.Parent = menu
local animScale = Instance.new("UIScale")
animScale.Name = "AnimScale"
animScale.Parent = menu

local function applySize()
	sizeScale.Scale = (userPercent / 100) / (isMobile and mobileDiv or 1)
end
applySize()

local loaded = false
local menuOpen = false

local function setMenu(open)
	if not loaded or open == menuOpen then return end
	menuOpen = open
	openMenu.Text = open and "<" or ">"
	if open then
		animScale.Scale = 0.9
		menu.Visible = true
		TweenService:Create(animScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
	else
		local tw = TweenService:Create(animScale, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = 0.9 })
		tw:Play()
		tw.Completed:Connect(function()
			if not menuOpen then menu.Visible = false end
		end)
	end
end

openMenu.MouseButton1Click:Connect(function() setMenu(not menuOpen) end)

-- Начальное состояние: видно только Load
local openerFade = collectFade(opener)
local loadFade = collectFade(loadFrame)
menu.Visible = false
opener.Visible = false
cursorFrame.Visible = false

-- Скрываем все панели заранее (списки для фейда собираем до этого)
local panelAlias = { Cofigs = "ConfigsPanel", KotsOwner = "OwnerPanel" }
local tabs = {}
local scrollTabs = menu.SideBar.Tabs.ScrollTabs

for _, slot in ipairs(scrollTabs:GetChildren()) do
	if slot:IsA("Frame") then
		local nm = (slot.Name:gsub("Slot$", ""))
		local tab = slot:FindFirstChild(nm)
		if tab then
			local panel = menu:FindFirstChild(panelAlias[nm] or (nm .. "Panel"))
			local t = {
				name = nm,
				order = slot.LayoutOrder,
				button = tab:FindFirstChild("Button"),
				selected = tab:FindFirstChild("Selected"),
				toggle = tab:FindFirstChild("Toggle"),
				panel = panel,
				fade = panel and collectFade(panel) or {},
			}
			table.insert(tabs, t)
		end
	end
end
table.sort(tabs, function(a, b) return a.order < b.order end)
for _, t in ipairs(tabs) do
	if t.panel then t.panel.Visible = false end
end

--------------------------------------------------------------------
-- ТАБЫ
--------------------------------------------------------------------
local hoverInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local panelInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local activeTab = nil

local function selectTab(t)
	if activeTab == t then return end
	local prev = activeTab
	activeTab = t
	if prev then
		if prev.toggle then TweenService:Create(prev.toggle, hoverInfo, { BackgroundTransparency = 1 }):Play() end
		if prev.panel then prev.panel.Visible = false end
	end
	if t.selected then TweenService:Create(t.selected, hoverInfo, { BackgroundTransparency = 1 }):Play() end
	if t.toggle then TweenService:Create(t.toggle, hoverInfo, { BackgroundTransparency = 0 }):Play() end
	if t.panel then
		setList(t.fade, false)
		t.panel.Visible = true
		fadeList(t.fade, true, panelInfo)
	end
end

for _, t in ipairs(tabs) do
	if t.selected then t.selected.BackgroundTransparency = 1 end
	if t.toggle then t.toggle.BackgroundTransparency = 1 end
	if t.button then
		t.button.MouseEnter:Connect(function()
			if activeTab ~= t and t.selected then
				TweenService:Create(t.selected, hoverInfo, { BackgroundTransparency = 0 }):Play()
			end
		end)
		t.button.MouseLeave:Connect(function()
			if t.selected then
				TweenService:Create(t.selected, hoverInfo, { BackgroundTransparency = 1 }):Play()
			end
		end)
		t.button.MouseButton1Click:Connect(function() selectTab(t) end)
	end
end
if tabs[1] then selectTab(tabs[1]) end

