local openKey = Enum.KeyCode.LeftControl
local rebinding = false

local function shortKey(kc)
	return (kc.Name:gsub("^Left", "L"):gsub("^Right", "R"))
end

local function makeBox(parent, refButton, text)
	local tb = Instance.new("TextBox")
	tb.Name = "Input"
	tb.AnchorPoint = Vector2.new(0.5, 0.5)
	tb.Position = refButton.Position
	tb.Size = UDim2.fromScale(0.2, 0.22)
	tb.BackgroundColor3 = Color3.fromHex("#2A2D36")
	tb.BorderSizePixel = 0
	tb.Text = text
	tb.TextColor3 = Color3.fromHex("#E8EAF0")
	tb.FontFace = Font.new("rbxasset://fonts/families/BuilderSans.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
	tb.TextScaled = true
	tb.ClearTextOnFocus = false
	tb.ZIndex = 3
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0.3, 0)
	corner.Parent = tb
	local pad = Instance.new("UIPadding")
	pad.PaddingLeft = UDim.new(0.1, 0)
	pad.PaddingRight = UDim.new(0.1, 0)
	pad.PaddingTop = UDim.new(0.1, 0)
	pad.PaddingBottom = UDim.new(0.1, 0)
	pad.Parent = tb
	local tc = Instance.new("UITextSizeConstraint")
	tc.MinTextSize = 8
	tc.MaxTextSize = 25
	tc.Parent = tb
	tb.Parent = parent
	refButton.Visible = false
	return tb
end

do
	local sRow = row("SettingsPanel", "PSlot")
	if sRow then
		-- Open menu button: клик -> нажми новую клавишу (Esc = отмена)
		local keyBtn = child(sRow, "functK1", "TextButton")
		if keyBtn then
			keyBtn.Text = shortKey(openKey)
			keyBtn.MouseButton1Click:Connect(function()
				rebinding = true
				keyBtn.Text = "..."
			end)
			UserInputService.InputBegan:Connect(function(input, gp)
				if rebinding then
					if input.UserInputType == Enum.UserInputType.Keyboard then
						rebinding = false
						if input.KeyCode ~= Enum.KeyCode.Escape then openKey = input.KeyCode end
						keyBtn.Text = shortKey(openKey)
					end
					return
				end
				if gp then return end
				if input.KeyCode == openKey then setMenu(not menuOpen) end
			end)
		end

		-- Menu size (%)
		local lbl2 = child(sRow, "functK2", "TextLabel")
		local trk2 = child(sRow, "functK2", "TextButton")
		if lbl2 and trk2 then
			lbl2.Text = "Menu size (%)"
			local box = makeBox(sRow, trk2, tostring(userPercent))
			box.FocusLost:Connect(function()
				local n = tonumber(box.Text)
				if n then userPercent = math.clamp(n, 30, 200) end
				box.Text = tostring(userPercent)
				applySize()
			end)
		end

		-- Mobile divisor
		local lbl3 = child(sRow, "functK3", "TextLabel")
		local trk3 = child(sRow, "functK3", "TextButton")
		if lbl3 and trk3 then
			lbl3.Text = "Phone size ÷ (1.5-2)"
			local box = makeBox(sRow, trk3, tostring(mobileDiv))
			box.FocusLost:Connect(function()
				local n = tonumber(box.Text)
				if n then mobileDiv = math.clamp(n, 1, 4) end
				box.Text = tostring(mobileDiv)
				applySize()
			end)
		end
	end
end


--------------------------------------------------------------------
-- JERK OFF (TrollPanel → Jerk)
--------------------------------------------------------------------
local function makeJerkOff()
    local J = { Enabled = false, wantsEnabled = false }
    local conns, tracks = {}, {}
    local tool = nil
    local toolEquippedConn = nil
    local toolUnequippedConn = nil

    local function stopAll()
        for _, c in pairs(conns) do c:Disconnect() end
        conns = {}
        for _, tr in pairs(tracks) do pcall(function() tr:Stop() end) end
        tracks = {}
    end

    local function playAnim(id, t1, t2, key)
        local char = localPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local a = Instance.new("Animation")
        a.AnimationId = "rbxassetid://" .. id
        local tr = hum:LoadAnimation(a)
        tracks[key] = tr
        conns[key] = RunService.RenderStepped:Connect(function()
            if J.Enabled then
                if tr.TimePosition >= t2 or tr.IsPlaying == false then
                    tr:Play(); tr.TimePosition = t1
                end
            else
                tr:Stop()
            end
        end)
        tr:Play(); tr.TimePosition = t1
    end

    local function startAnims()
        stopAll()
        playAnim("72042024",  0.5, 0.9,   1)
        playAnim("168268306", 1,   1.001, 2)
    end

    -- создаёт Tool, но НЕ надевает — только вешает обработчики
    local function makeTool()
        local t = Instance.new("Tool")
        t.Name = "Jerk Off"
        t.RequiresHandle = false

        toolEquippedConn = t.Equipped:Connect(function()
            if J.wantsEnabled then
                J.Enabled = true
                startAnims()
            end
        end)
        toolUnequippedConn = t.Unequipped:Connect(function()
            J.Enabled = false
            stopAll()
        end)

        return t
    end

    local function removeTool()
        if toolEquippedConn then toolEquippedConn:Disconnect(); toolEquippedConn = nil end
        if toolUnequippedConn then toolUnequippedConn:Disconnect(); toolUnequippedConn = nil end
        stopAll()
        J.Enabled = false
        if tool then
            -- если надет — сначала снимаем
            local char = localPlayer.Character
            if char and tool.Parent == char then
                local bp = localPlayer:FindFirstChildOfClass("Backpack")
                if bp then tool.Parent = bp end
            end
            tool:Destroy()
            tool = nil
        end
    end

    function J.Enable()
        J.wantsEnabled = true
        if tool and tool.Parent then return end
        local bp = localPlayer:FindFirstChildOfClass("Backpack")
            or localPlayer:WaitForChild("Backpack", 5)
        if not bp then return end
        tool = makeTool()
        tool.Parent = bp       -- ← просто кладём в рюкзак
        -- никакого EquipTool, никакой playAnim здесь
    end

    function J.Disable()
        J.wantsEnabled = false
        removeTool()
    end

    localPlayer.CharacterAdded:Connect(function()
        -- чистка от старого персонажа
        if toolEquippedConn then toolEquippedConn:Disconnect(); toolEquippedConn = nil end
        if toolUnequippedConn then toolUnequippedConn:Disconnect(); toolUnequippedConn = nil end
        if tool then pcall(function() tool:Destroy() end); tool = nil end

        -- подчищаем возможные «осиротевшие» копии в новом/старом рюкзаке
        local bp = localPlayer:FindFirstChildOfClass("Backpack")
        if bp then
            for _, c in ipairs(bp:GetChildren()) do
                if c:IsA("Tool") and c.Name == "Jerk Off" then
                    c:Destroy()
                end
            end
        end

        stopAll()
        J.Enabled = false

        if J.wantsEnabled then
            task.wait(1)
            if J.wantsEnabled then J.Enable() end
        end
    end)

    return J
end

--------------------------------------------------------------------
-- NO STUN (Killer & Survival — держит WalkSpeed по команде)
--------------------------------------------------------------------
local function makeNoStun()
    local N = { users = 0 }
    local conn = nil

    local TEAM_SPEED = {
        Survival = 17.5,
        Killer   = 19.125,
        Survivors = 17,
        Spectator = 17,
    }
    local DEFAULT_SPEED = 17

    local function resolveSpeed()
        local team = localPlayer.Team
        if team then
            local exact = TEAM_SPEED[team.Name]
            if exact then return exact end
            -- мягкий поиск на случай другого написания ("Survivor", "Killers" и т.п.)
            local lower = string.lower(team.Name)
            if string.find(lower, "surv") then return 18 end
            if string.find(lower, "kill") then return 19.125 end
        end
        return DEFAULT_SPEED
    end

    local function apply()
        local char = localPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local speed = resolveSpeed()
        if hum.WalkSpeed ~= speed then
            hum.WalkSpeed = speed
        end
    end

    function N.Acquire()
        N.users += 1
        if N.users == 1 then
            apply()
            conn = RunService.RenderStepped:Connect(apply)
        end
    end

    function N.Release()
        N.users = math.max(0, N.users - 1)
        if N.users == 0 and conn then
            conn:Disconnect()
            conn = nil
            local char = localPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = DEFAULT_SPEED end
        end
    end

    return N
end

