--------------------------------------------------------------------
-- ЗАГРУЗКА (ProgressLoad 0 -> 100 за 4-6 сек, с притормаживаниями)
--------------------------------------------------------------------
task.spawn(function()
	local bar = UI.Bars["ProgressLoad"]
	local function setProgress(x) UI.SetProgressClip(bar.fill, bar.paint, x) end
	setProgress(0)

	local rng = Random.new()
	local total = rng:NextNumber(4, 6)
	local count = rng:NextInteger(6, 9)
	local incs, sumI = {}, 0
	for i = 1, count do
		incs[i] = rng:NextNumber(0.5, 1.5)
		sumI += incs[i]
	end
	local stallA = rng:NextInteger(2, count - 1)
	local stallB = rng:NextInteger(2, count - 1)
	local durs, sumD = {}, 0
	for i = 1, count do
		incs[i] = incs[i] / sumI
		local speed = rng:NextNumber(0.8, 1.5)
		if i == stallA or i == stallB then speed = rng:NextNumber(0.35, 0.55) end -- притормаживание
		durs[i] = incs[i] / speed
		sumD += durs[i]
	end
	local keys = { { 0, 0 } }
	local t, p = 0, 0
	for i = 1, count do
		t += durs[i] / sumD * total
		p += incs[i]
		table.insert(keys, { t, p })
	end
	keys[#keys][2] = 1

	local start = os.clock()
	while true do
		local el = os.clock() - start
		if el >= total then break end
		local value = 1
		for i = 2, #keys do
			if el <= keys[i][1] then
				local k0, k1 = keys[i - 1], keys[i]
				local a = (el - k0[1]) / math.max(k1[1] - k0[1], 1e-6)
				a = a * 0.5 + (a * a * (3 - 2 * a)) * 0.5
				value = k0[2] + (k1[2] - k0[2]) * a
				break
			end
		end
		setProgress(value)
		RunService.RenderStepped:Wait()
	end
	setProgress(1)
	task.wait(0.3)

	-- Load плавно исчезает
	fadeList(loadFade, false, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out))
	task.wait(0.7)
	loadFrame.Visible = false

	-- Opener плавно появляется
	setList(openerFade, false)
	opener.Visible = true
	fadeList(openerFade, true, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out))
	loaded = true
end)

end)(screenGui, UI)
